// ===================== CONFIGURAÇÃO =====================
const CFG = {
  // Para testar: só estes telefones entram (lista vazia = todos)
  numeros_liberados: [],
  totalFollowups: 4,
  // Não manda nada se teve qualquer mensagem na conversa nas últimas X horas
  // (conversa em andamento ou follow-up já enviado hoje)
  intervaloMinHoras: 10
};
// Templates aprovados na Meta (conta da Mia) - {{1}} = primeiro nome do lead
const TEMPLATES = {
  1: { nome: 'mia_followup_1', texto: 'Oii {{1}}! Tudo bem? Vi que você ainda não respondeu. Fica à vontade, tá tudo tranquilo! Só queria saber se ficou alguma dúvida sobre como a M[IA] pode ajudar sua empresa. 😊' },
  2: { nome: 'mia_followup_2', texto: 'Tudo bem, {{1}}? Tem um minutinho? 😄' },
  3: { nome: 'mia_followup_3', texto: 'Opa {{1}}!!, sabia que empresas que implementam IA reduzem até 40% do tempo em tarefas operacionais? A M[IA] já fez isso acontecer para vários negócios. Faz sentido a gente conversar 30 minutinhos sobre isso?' },
  4: { nome: 'mia_followup_4', texto: 'Oi {{1}}! Tenho um caso aqui que acho que vai te interessar. Um dos nossos clientes automatizou o atendimento e triplicou a capacidade de resposta sem contratar ninguém. Quer entender como funciona na prática?' }
};
// ========================================================
// Saída: um item por lead em Follow-up, com "acao":
//   agendar  -> respondeu depois de um follow-up
//   perda    -> recebeu os 4 e não respondeu
//   enviar   -> manda o próximo follow-up
//   ignorar  -> não faz nada hoje (o campo "motivo" explica)

const last8 = v => String(v || '').replace(/\D/g, '').slice(-8);
const tipo = r => String(r.message_type || '');
const isRet = r => tipo(r) === 'retomada';
const isLead = r => !tipo(r).startsWith('retomada') && String(r.mensagem_usuario || '').trim() !== '';
const ts = r => new Date(r.created_at).getTime();
const agora = Date.now();
const liberados = CFG.numeros_liberados.map(last8);

// Histórico agrupado pelos 8 últimos dígitos do telefone
const porTel = {};
for (const it of $('Ler histórico (30 dias)').all()) {
  const r = it.json;
  if (!r || !r.telefone || !r.created_at) continue;
  const k = last8(r.telefone);
  if (k.length === 8) (porTel[k] = porTel[k] || []).push(r);
}

const saida = [];
const vistos = new Set();
for (const it of $('Cliente de cada contrato (Flow)').all()) {
  const lead = it.json;
  if (!lead || !lead.id || vistos.has(lead.id)) continue;
  vistos.add(lead.id);

  let contatos = lead.social_media && lead.social_media.contacts;
  if (typeof contatos === 'string') { try { contatos = JSON.parse(contatos); } catch { contatos = []; } }
  if (!Array.isArray(contatos)) contatos = [];

  const chaves = [...new Set([lead.whatsapp, lead.phone, ...contatos.map(c => c && c.whatsapp)]
    .map(last8).filter(k => k.length === 8))];
  const rows = chaves.flatMap(k => porTel[k] || []).sort((a, b) => ts(a) - ts(b));

  const ultimaLead = [...rows].reverse().find(isLead);
  const ultimaRet = [...rows].reverse().find(isRet);
  const tLead = ultimaLead ? ts(ultimaLead) : 0;
  const tRet = ultimaRet ? ts(ultimaRet) : 0;
  const ultima = rows[rows.length - 1];

  const nomeCompleto = String(lead.contact_name || (ultimaLead && ultimaLead.nome_usuario) || lead.name || '').trim();
  const base = {
    lead_id: lead.id,
    empresa: lead.name,
    etapa_atual: 'Follow-up',
    telefone: ultima ? String((ultimaLead || ultima).telefone) : (lead.whatsapp || lead.phone || ''),
    chat_id: ultima ? String(ultima.id_usuario || (ultimaLead && ultimaLead.id_usuario) || '') : '',
    nome_usuario: nomeCompleto,
    primeiro_nome: nomeCompleto.split(/\s+/)[0] || 'tudo bem'
  };
  const ignorar = motivo => saida.push({ json: { ...base, acao: 'ignorar', motivo } });

  if (liberados.length && !chaves.some(k => liberados.includes(k))) { ignorar('fora da lista de teste (numeros_liberados)'); continue; }
  if (!chaves.length) { ignorar('sem telefone/WhatsApp no cadastro'); continue; }
  if (!rows.length) { ignorar('sem conversa no WhatsApp nos últimos 30 dias'); continue; }

  // 1) Respondeu depois de algum follow-up -> Agendar reunião
  if (tRet && tLead > tRet) { saida.push({ json: { ...base, acao: 'agendar' } }); continue; }

  if (rows.some(r => tipo(r) === 'retomada_fim' && ts(r) > tLead)) { ignorar('já encerrado pelo fluxo antigo, sem resposta depois'); continue; }

  const horas = (agora - ts(ultima)) / 3600000;
  if (horas < CFG.intervaloMinHoras) { ignorar('teve mensagem há ' + horas.toFixed(1) + 'h (espera ' + CFG.intervaloMinHoras + 'h)'); continue; }

  const enviados = rows.filter(r => isRet(r) && ts(r) > tLead).length;

  // 2) Já recebeu os 4 e não respondeu -> Lead Perdido
  if (enviados >= CFG.totalFollowups) { saida.push({ json: { ...base, acao: 'perda', numero: enviados } }); continue; }

  // 3) Manda o próximo follow-up
  const numero = enviados + 1;
  const t = TEMPLATES[numero];
  saida.push({ json: { ...base, acao: 'enviar', numero, template: t.nome, texto: t.texto.replace('{{1}}', base.primeiro_nome) } });
}
return saida;

const decisoes = $('Decidir ação de cada lead').all();
const convs = $input.all();
const saida = [];
decisoes.forEach((d, i) => {
  const conv = (convs[i] && convs[i].json) || {};
  const humano = !!(conv.meta && conv.meta.assignee);
  const erro = !!conv.error;
  if (d.json.acao !== 'agendar' && (humano || erro)) return;
  saida.push({ json: d.json });
});
return saida;

